const updateIssue = `-- name: UpdateIssue :one
UPDATE issues
SET title       = COALESCE($1, title),
    description = COALESCE($2, description),
    state_id    = COALESCE($3, state_id),
    priority    = COALESCE($4, priority),
    sort_order  = COALESCE($5, sort_order),
    label_ids   = COALESCE($6::uuid[], label_ids),
    subscriber_ids = COALESCE($7::uuid[], subscriber_ids),
    assignee_id = CASE WHEN $8::boolean THEN $9 ELSE assignee_id END,
    due_date    = CASE WHEN $10::boolean THEN $11 ELSE due_date END,
    project_id  = CASE WHEN $12::boolean THEN $13 ELSE project_id END,
    milestone_id = CASE WHEN $14::boolean THEN $15 ELSE milestone_id END,
    cycle_id    = CASE WHEN $16::boolean THEN $17 ELSE cycle_id END,
    parent_id   = CASE WHEN $18::boolean THEN $19 ELSE parent_id END,
    updated_at  = now()
WHERE id = $20
RETURNING id, workspace_id, team_id, number, title, description, state_id, priority, assignee_id, creator_id, sort_order, created_at, updated_at, archived_at, label_ids, due_date, subscriber_ids, project_id, milestone_id, cycle_id, parent_id, started_at, completed_at, logged_seconds
`

type UpdateIssueParams struct {
	Title         *string
	Description   *string
	StateID       *uuid.UUID
	Priority      *int16
	SortOrder     *float64
	LabelIds      []uuid.UUID
	SubscriberIds []uuid.UUID
	SetAssignee   bool
	AssigneeID    *uuid.UUID
	SetDueDate    bool
	DueDate       *time.Time
	SetProject    bool
	ProjectID     *uuid.UUID
	SetMilestone  bool
	MilestoneID   *uuid.UUID
	SetCycle      bool
	CycleID       *uuid.UUID
	SetParent     bool
	ParentID      *uuid.UUID
	ID            uuid.UUID
}

// NULL arguments leave their column unchanged. Columns that can be cleared
// (assignee, due date) are only touched when their set_ flag is true.
func (q *Queries) UpdateIssue(ctx context.Context, arg UpdateIssueParams) (Issue, error) {
	row := q.db.QueryRow(ctx, updateIssue,
		arg.Title,
		arg.Description,
		arg.StateID,
		arg.Priority,
		arg.SortOrder,
		arg.LabelIds,
		arg.SubscriberIds,
		arg.SetAssignee,
		arg.AssigneeID,
		arg.SetDueDate,
		arg.DueDate,
		arg.SetProject,
		arg.ProjectID,
		arg.SetMilestone,
		arg.MilestoneID,
		arg.SetCycle,
		arg.CycleID,
		arg.SetParent,
		arg.ParentID,
		arg.ID,
	)
	var i Issue
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.TeamID,
		&i.Number,
		&i.Title,
		&i.Description,
		&i.StateID,
		&i.Priority,
		&i.AssigneeID,
		&i.CreatorID,
		&i.SortOrder,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ArchivedAt,
		&i.LabelIds,
		&i.DueDate,
		&i.SubscriberIds,
		&i.ProjectID,
		&i.MilestoneID,
		&i.CycleID,
		&i.ParentID,
		&i.StartedAt,
		&i.CompletedAt,
		&i.LoggedSeconds,
	)
	return i, err
}

